type Item = { id: string; label: string };
const list = useListbox<Item>({ items });        // state + getters, typed
return (
  <ul {...list.getListProps()} role="listbox">
    {items.map((it, index) => (
      <li {...list.getItemProps({ item: it, index })} key={it.id}>{it.label}</li>
    ))}
  </ul>
);

